// ── #122 (المرحلة أ) — **إطارٌ يحاكي المشغّل، لا قائمةٌ رأسيّة** ────────────
//
// ⭐ **قرار المالك:** القائمةُ الرأسيّة **تُستبدَل** بإطارٍ يحاكي مشغّل يوتيوب
// وفيه **شريطٌ أفقيّ سفليّ**: أزرارُنا **تُسحب داخله فتُفعَّل** · **وتُحرَّك فيه
// فيتغيّر ترتيبُها** · **وتُسحب خارجه فتُطفأ** — **وموضعُها محفوظٌ في الحالين.**
// ⛔ **ولا تُضاف إلى القائمة: تُستبدَل بها** — **فلا موضعان لحقيقةٍ واحدة.**
//
// ⛔ **وأزرارُ يوتيوب لا تدخل هذا الإطار في هذي المرحلة** — تلك المرحلة (ب)،
// **وهي عرضٌ لا تحكّم**: الـ38 مفتاحاً في Clean Player تبقى **المكانَ الوحيد
// للتغيير**، **فالإطارُ مرآةٌ لا مصدر.**
//
// ⛔⭐ **ومسارُ لوحة المفاتيح شرطٌ (#77) لا يُلغيه المحاكي** — **بل يزداد لزوماً:
// واجهةُ سحبٍ بلا لوحة مفاتيح تستبدل الوضوحَ بإخفاء.** **والأسهمُ تُحرّك،
// والمسافةُ تُدخل الزرَّ الشريطَ وتُخرجه، ومنطقةٌ حيّة تقول أين استقرّ وفي أيّ
// منطقة** — **ولا يُترك ذلك للرسم وحده.**
//
// ⚠️ **والشريطُ `direction: ltr` صراحةً** — كما `.grid` و`.vzGrid`: **صفحتُنا
// عربيّةٌ RTL وشريطُ يوتيوب LTR**، **فبلا التصريح ينقلب معنى «قبل» و«بعد» بين
// المحرِّر والحقن** ⇒ **معاينةٌ تكذب، وهي ما بُني هذا كلُّه لمنعه.**
const VZ_SIM_ZONES = { in: "داخل الشريط", out: "خارج الشريط" };

function vzUiBuildBarEditor(doc, root, opts = {}) {
  const { get, set } = opts;
  root.textContent = "";

  const sim = doc.createElement("div");
  sim.className = "vzSim";
  const screen = doc.createElement("div");
  screen.className = "vzSimScreen";
  const hint = doc.createElement("span");
  hint.className = "vzSimHint";
  hint.textContent = "معاينةُ المشغّل";
  const bar = doc.createElement("div");
  bar.className = "vzSimBar";
  bar.dataset.vzZone = "in";
  bar.setAttribute("role", "listbox");
  bar.setAttribute("aria-label", "داخل الشريط — بترتيب الظهور");
  // ── #123 (المرحلة ب) — **مجموعتان كما في يوتيوب، بترتيبٍ مقيس** ────────────
  // **المقيس على `youtube.com/watch` 2026-08-07 بالموضع الأفقيّ لا ببنية الأبناء**
  // (فالمجموعةُ تحوي أغلفة): **يسار `play@12 · mute@64 · time@104`** ·
  // **يمين `subtitles@533 · settings@581 · size@629 · fullscreen@677`**.
  // ⛔ **ومعاينةٌ بترتيبٍ لا وجود له معاينةٌ تكذب** — وهي ما بُني هذا كلُّه لمنعه.
  //
  // ── #129 (المرحلة ج) — **الإطارُ يحاكي ملءَ الشاشة، بقياسٍ أُعيد فيه** ──────
  // ⛔⭐⭐ **وقاعدةُ «ما لم يثبت لا يدخل» لم تسقط: تغيّر مجالُها** — أُعيد القياسُ
  // في ملء الشاشة نفسِه (`tools/bench-129-fs-layout.mjs`) **ولم يُنقل حكمُ النافذة**.
  // **والمقيس 2026-08-07 على `watch` في ملء الشاشة** (شاشة `800×600`):
  //   · **العنوان** `.ytp-fullscreen-metadata` **`466×56@322,8`** — وفي النافذة
  //     `display:none` ⇒ **الانقلابُ مقيسٌ لا مفترَض** (قرار 125).
  //   · **صفُّ الإجراءات** `.ytp-fullscreen-quick-actions` **`232×40@12,480`**،
  //     **فوق شريط التقدّم** (`@12,538`) — **خمسةُ أزرار** بمواضعها
  //     `16 · 64 · 112 · 160 · 208`.
  //   · **الشريط السفليّ** `@12,552`: **يسار** `play@12 · mute@64 · time@104` ·
  //     **وسط** «المزيد من الفيديوهات» `@380` · **يمين** `autonav@592 ·
  //     subtitles@640 · settings@688 · fullscreen@736`.
  //   · ⛔ **ووضعُ السينما `display:none` هناك** ⇒ **رُفع من الإطار** (وبقي مفتاحُه).
  // ⚠️ **وثلاثةُ حدودٍ تُكتب في الإطار نفسِه لا في السجلّ** — أدناه في `limits`.
  const gLeft = doc.createElement("div");
  gLeft.className = "vzSimGroup vzSimLeft";
  const gCenter = doc.createElement("div");
  gCenter.className = "vzSimGroup vzSimCenter";
  const gRight = doc.createElement("div");
  gRight.className = "vzSimGroup vzSimRight";
  bar.appendChild(gLeft);
  bar.appendChild(gCenter);
  bar.appendChild(gRight);

  // **شريطُ العنوان أعلى الصورة** — نصٌّ لا أيقونة (مقيسٌ: العنوان والقناة معاً)
  const title = doc.createElement("div");
  title.className = "vzSimTitle";
  title.setAttribute("aria-hidden", "true");
  // **صفُّ الإجراءات فوق شريط التقدّم** — والترتيبُ ترتيبُ المواضع المقيسة
  const acts = doc.createElement("div");
  acts.className = "vzSimActions";
  acts.setAttribute("aria-hidden", "true");
  // ⛔⭐ **وشريطُ التقدّم يُرسم وهو بلا مفتاحٍ في Clean Player** (قرار المالك):
  // **الإطارُ مُحاكٍ لا لوحةُ ضوابط** — **وبلا شريطِ تقدّمٍ لا يشبه المشغّل أصلاً،
  // ومحاكاةٌ ناقصةٌ في تشريحه تُضعف كلَّ ما بُني عليها.**
  // ⚠️ **وإخفاؤه ميزةُ #70 (السكون) لا هذا القسم** — مكتوبٌ في تلميحه كي لا
  // يُبحث عن مربّعٍ لا وجود له.
  const prog = doc.createElement("div");
  prog.className = "vzSimProgress";
  prog.setAttribute("aria-hidden", "true");
  prog.title = "شريطُ التقدّم — لا مفتاحَ له في Clean Player، وإخفاؤه ميزةُ السكون (#70)";
  const progFill = doc.createElement("span");
  progFill.className = "vzSimProgressFill";
  prog.appendChild(progFill);

  screen.appendChild(hint);
  screen.appendChild(title);
  screen.appendChild(acts);
  screen.appendChild(prog);
  screen.appendChild(bar);

  const tray = doc.createElement("div");
  tray.className = "vzSimTray";
  tray.dataset.vzZone = "out";
  tray.setAttribute("role", "listbox");
  tray.setAttribute("aria-label", "خارج الشريط — لا تظهر في المشغّل");
  const trayLbl = doc.createElement("span");
  trayLbl.className = "vzSimTrayLbl";
  trayLbl.textContent = "خارج الشريط";
  tray.appendChild(trayLbl);

  const note = doc.createElement("p");
  note.className = "vzSimNote";
  note.hidden = true;
  sim.appendChild ? null : null;

  const live = doc.createElement("p");
  live.className = "vzBarLive";
  live.setAttribute("aria-live", "polite");
  live.setAttribute("role", "status");

  // ── ⛔⭐⭐ #129 — **حدودُ المعاينة تُكتب فيها، لا في سجلٍّ يُقرأ مرّة** ────────
  // **والثلاثةُ كلُّها مقيسة، ولا واحدَ منها استنتاج:**
  //  (١) **تخطيطُ ملء الشاشة** — وفي النافذة **لا شريطَ عنوانٍ ولا صفَّ إجراءات**
  //      (`display:none` في الحالين، مقيسٌ في التشغيلة نفسِها).
  //  (٢) ⭐ **وعلى صفحة المشاهدة** — **وفي قوائم التشغيل يختفي العنوانُ والصفُّ
  //      والشبكةُ ومفتاحُ التشغيل التلقائيّ، ويظهر «السابق» `52×40`**. ⭐ **وهذا
  //      حدٌّ كشفه القياسُ ولم نكن نعرفه** — فلولا إعادةُ القياس لَوعدت المعاينةُ
  //      بأربعةٍ لا تقع في قائمة تشغيل.
  //  (٣) **ووضعُ السينما `display:none` في ملء الشاشة** فرُفع رسمُه من الإطار.
  const limits = doc.createElement("ul");
  limits.className = "vzSimLimits";
  for (const t of [
    "هذا تخطيطُ ملء الشاشة — وفي النافذة لا يظهر شريطُ العنوان ولا صفُّ الإجراءات.",
    "وهو تخطيطُ صفحة المشاهدة — وفي قوائم التشغيل يختفي العنوانُ وصفُّ الإجراءات وشبكةُ «المزيد» ومفتاحُ التشغيل التلقائيّ، ويظهر زرُّ «السابق».",
    "وزرُّ وضع السينما لا يظهر هنا: قِيس أنه مخفيٌّ في ملء الشاشة — ومفتاحُه باقٍ لأن الزرَّ حيٌّ في النافذة."
  ]) {
    const li = doc.createElement("li");
    li.textContent = t;
    limits.appendChild(li);
  }

  sim.appendChild(screen);
  sim.appendChild(note);
  sim.appendChild(limits);
  sim.appendChild(tray);
  root.appendChild(sim);
  root.appendChild(live);
  const helps = doc.createElement("div");
  helps.className = "vzSimHelps";
  root.appendChild(helps);

  const meta = (id) => VZ_BAR_BUTTONS.find((b) => b.id === id) || { id, label: id, help: "" };
  const say = (m) => { live.textContent = m; };
  const list = () => (get && get()) || [];
  const posOf = (id) => list().findIndex((x) => x.id === id) + 1;

  // ── #123 — **عناصرُ يوتيوب: عرضٌ لا تحكّم، والاتّجاه واحد** ────────────────
  //
  // ⛔⭐⭐ **الاتّجاه: Clean Player ⇒ الإطار، ولا عكس** (قرار المالك): أخفى عنصراً
  // بمفتاحه ⇒ **اختفى من الإطار فوراً**. ⇒ **فالإطارُ معاينةٌ حيّةٌ لأثر Clean
  // Player**، **والـ38 مفتاحاً تبقى المكانَ الوحيد للتغيير** — **مرآةٌ لا مصدر.**
  // ⛔ **ولا اتّجاهَ عكسيّ ولو بدا مريحاً: موضعان لحقيقةٍ واحدة.**
  //
  // ⭐ **والقائمةُ تُشتقّ من `VZ_UI_CLEAN` نفسِه** — **لا قائمةَ ثانية تُكتب بيد**:
  // مفتاحٌ يُضاف غداً **يظهر في الإطار بإعلان جهته وترتيبه**، ولا يُنسى في موضعين.
  // ⚠️ **وما لم يثبت في القياس لا يُعلَن جهةً فلا يدخل** — **وعنصرٌ في الإطار لا
  // يوجد عند المستخدم معاينةٌ تكذب، وهي أسوأ من غياب المعاينة.**
  //
  // ⛔⭐⭐ **والفرقُ عن أزرارنا بنيويٌّ لا تلميح** (بوّابةُ قبولٍ من المالك):
  // **`pointer-events: none` على عناصر العرض** ⇒ **لا يمكن سحبُها أصلاً، ولا
  // يتبدّل المؤشّرُ فوقها** — **فلا يقع «سحبتُه فلم يحدث شيء»**، وهو «لا أثرَ بلا
  // خطأ» الذي أنفقنا فيه أسبوعاً. **ومعه فرقٌ في المظهر: بلا إطارٍ وباهتة.**
  // ⚠️ **ولا تدخل حلقةَ التركيز** (`aria-hidden` وبلا `tabindex`): **ما لا
  // يُتفاعل معه لا يُركَّز عليه**، **وإدخالُه يُطيل الحلقة بلا فائدة.**
  const ytParts = () => Object.entries(VZ_UI_CLEAN)
    .filter(([, v]) => v && v.شريط)
    .map(([key, v]) => ({ key, ...v.شريط, label: v.label }))
    .sort((a, b) => a.ترتيب - b.ترتيب);

  // ⭐ **المنطقةُ تُعلَن ولا تُستنتَج** — خمسُ مناطق، ولكلِّ عنصرٍ منطقتُه في
  // `VZ_UI_CLEAN[key].شريط.جهة`. **ومنطقةٌ لا يعرفها هذا الجدول تُسقط العنصر**
  // بدل أن تضعه في مكانٍ يُختار له، **فمعاينةٌ بموضعٍ مخترَع معاينةٌ تكذب.**
  const zoneOf = (جهة) => ({ "علوي": title, "إجراءات": acts,
                             "يسار": gLeft, "وسط": gCenter, "يمين": gRight })[جهة] || null;

  function renderYouTube() {
    for (const g of [gLeft, gCenter, gRight, title, acts]) {
      g.querySelectorAll("[data-vz-yt]").forEach((e) => e.remove());
    }
    const cp = (opts && opts.cleanPlayer && opts.cleanPlayer()) || { enabled: false, items: {} };
    // ── ⛔⭐ سطرٌ يشرح ولا يمنع (قرار المالك 2026-08-07) ──────────────────────
    // **الواقعة:** أشّر المالكُ مربّعاً و**المفتاحُ الرئيسيّ مطفأ** ⇒ **لم يتغيّر
    // الإطار** — **وهو صادق** (Clean Player مطفأ ⇒ يوتيوب يعرض كلَّ شيء)،
    // **لكنه لا يقول ذلك.** ⇒ **فيُقال.**
    // ⛔ **ولا تُعطَّل المربّعات** (قرار المالك، وهو تضييقٌ على قاعدة #24):
    // **ليست ميتةً — تحفظ قيمةً تعمل حين يُشغَّل المفتاح** ⇒ **وتعطيلُها يُخفي
    // عن المالك ما ضبطه.** ⇒ **فالسطرُ يشرح ولا يمنع.**
    note.hidden = !!cp.enabled;
    note.textContent = "Clean Player مطفأ — لا شيءَ يُخفى، وما تؤشّره هنا محفوظٌ ويعمل حين تُشغّله.";
    for (const part of ytParts()) {
      // **مخفيٌّ في Clean Player ⇒ مخفيٌّ هنا** — وهو الاتّجاه الوحيد
      if (cp.enabled && cp.items && cp.items[part.key] === true) continue;
      const host = zoneOf(part.جهة);
      if (!host) continue;                       // منطقةٌ لا تُعرف ⇒ لا يُخترع لها موضع
      const el = doc.createElement("span");
      el.className = "vzSimYt";
      el.dataset.vzYt = part.key;
      const svg = (k) => {
        // ⭐ **الراسمُ الواحد** (#131) — ولا وسمَ يُبنى هنا بيد
        return vzSvg(VZ_SIM_ICONS[k], { size: 18, mode: "fill", key: k });
      };
      const ico = VZ_SIM_ICONS[part.أيقونة || part.key];
      if (part.أيقونات) {
        // **صفُّ الإجراءات: خمسُ أيقوناتٍ ومفتاحٌ واحد** — مقيسٌ أن المفتاح
        // يُخفي الصفَّ كلَّه، **فلا يُوعَد بمفتاحٍ لكلّ زرّ**
        el.classList.add("vzSimIco", "vzSimActionSet");
        el.innerHTML = part.أيقونات.map(svg).join("");
      } else if (part.شكل === "مفتاح") {
        // ⭐ **التشغيلُ التلقائيّ يُرسم بشكلٍ لا بأيقونة — والسببُ مقيس** (#129):
        // **`svg=0 · img=0 · لا صورةَ خلفية`** ⇒ **فقِيس بأيّ شيءٍ يُرسم.**
        // ⛔⭐⭐ **وأوّلُ قياسٍ أصاب عنصراً واحداً فأنتج رسماً كاذباً** (#130):
        // قُرئ `.ytp-autonav-toggle-button` **`30×18` أبيضُ** فرُسم **شكلاً أبيضَ
        // صلباً** — **والحقيقيُّ مسارٌ ومقبضٌ**: ذلك العنصرُ هو **المسار**،
        // **والمقبضُ `::after` عليه**. ⇒ **فبنيةٌ من عنصرين قُرئ منها واحد.**
        // **والمقيس بحروفه (2026-08-07، في ملء الشاشة، الحالان معاً):**
        //   · **المسار** `30×18` نصفُ قطره `9px` ومزاحٌ `translateY(-9px)` —
        //     **مشغَّل: `#fff`** · **مطفأ: `rgba(255,255,255,.1)`**
        //   · **المقبض** `::after` — `14×14` نصفُ قطره `7px` `margin:2px`
        //     `top/left:0` — **مشغَّل: `#000` ومزاحٌ `translateX(12px)`** ·
        //     **مطفأ: `#fff` بلا إزاحة.**
        // ⛔⭐⭐ **وثالثةٌ في العنصر نفسِه** (#132): **المقبضُ فيه رسمٌ لم يُقَس** —
        // **وآليّتُه قُرئت ولا تُفترض**: `background-image` بـ`data:` مُرمَّزٍ على
        // `::after`، **مقاسُه `9px` داخل مقبضٍ `14×14`**. ⇒ **فصار المقبضُ عنصراً
        // يحمل أيقونتَه من السجلّ** — **لا زائفاً فارغاً يُقرأ مقبضاً.**
        // ⭐ **ورسمٌ واحدٌ ثابت: حالُ التشغيل وحدَها ولا يتغيّر بالنقر** (قرار
        // المالك) — **فالإطارُ معاينةٌ لا مفتاحٌ يُضغَط**، وعناصرُ يوتيوب فيه
        // `pointer-events: none` أصلاً.
        el.classList.add("vzSimSwitch");
        const track = doc.createElement("i");
        track.className = "vzSimSwitchTrack";
        const knob = doc.createElement("i");
        knob.className = "vzSimSwitchKnob";
        knob.innerHTML = vzSvg(VZ_SIM_ICONS.autonav_knob_play,
          { size: 9, mode: "fill", key: "autonav_knob_play" });
        track.appendChild(knob);
        el.appendChild(track);
      } else if (part.نصّ) {
        el.classList.add("vzSimTitleText");
        el.textContent = part.نصّ;
      } else if (ico) {
        // ⛔ **الأيقونةُ من النسخة المحروسة** — لا رسمٌ هنا ولا رمزٌ يُقارِب
        el.innerHTML = svg(part.أيقونة || part.key);
        el.classList.add("vzSimIco");
      } else {
        // **والوقتُ نصٌّ لا أيقونة** — مقيسٌ، ولا تُخترع له صورة
        el.textContent = (typeof VZ_YT_TEXT_LOCAL === "object" && VZ_YT_TEXT_LOCAL[part.key]) || part.رمز;
      }
      el.setAttribute("aria-hidden", "true");   // خارج حلقة التركيز
      // ⭐ **وحدُّ العنصر يُقرأ عنده لا في سجلٍّ بعيد** — فمن رأى في مشغّله غيرَ
      // ما في الإطار يجد السببَ في تلميحه، لا في ملفٍّ لا يفتحه
      el.title = `${part.label.replace(/^إخفاء /, "")} — عرضٌ فقط، ويُخفى من Clean Player` +
        (part.حدّ ? ` · ${part.حدّ}` : "");
      host.appendChild(el);
    }
    // **حاويةٌ فرغت لا تترك أثراً** — فصفُّ إجراءاتٍ مخفيٌّ لا يُبقي فراغَه
    title.hidden = !title.querySelector("[data-vz-yt]");
    acts.hidden = !acts.querySelector("[data-vz-yt]");
  }

  function render() {
    const l = list();
    renderYouTube();
    bar.querySelectorAll("[data-vz-bar-id]").forEach((e) => e.remove());
    tray.querySelectorAll("[data-vz-bar-id]").forEach((e) => e.remove());
    helps.textContent = "";
    for (const it of l) {
      const m = meta(it.id);
      const chip = doc.createElement("button");
      chip.type = "button";
      chip.className = it.on ? "vzSimBtn" : "vzSimBtn vzSimOff";
      chip.dataset.vzBarId = it.id;
      chip.draggable = true;
      chip.tabIndex = 0;
      chip.setAttribute("role", "option");
      chip.setAttribute("aria-selected", String(!!it.on));
      // ⭐ **أيقونتُنا المشحونة نفسُها** — لا نسخةٌ ثانية تُرسم للمعاينة
      // ── #126 — **أيقونةٌ بلا نصّ، كأيقونات يوتيوب** (قرار المالك) ──────────
      // ⚠️ **والاسمُ لا يسقط: يبقى في `aria-label` وفي التلميح** — **فما حُذف
      // هو النصُّ المرسوم لا المعنى**، **ومن لا يرى الرسمَ يقرؤه كما كان.**
      const ourIco = VZ_SIM_OUR_ICONS[it.id === "speed" ? "speed" : "filter-h"];
      if (ourIco) {
        chip.innerHTML = vzSvg(ourIco, { size: 20, key: it.id });
        chip.title = m.label;
      } else {
        chip.textContent = m.label;
      }
      // **الوصفُ يقول المنطقةَ والموضعَ معاً** — فقارئُ الشاشة لا يرى الإطار
      chip.setAttribute("aria-label",
        `${m.label} — ${it.on ? VZ_SIM_ZONES.in : VZ_SIM_ZONES.out}، الموضع ${posOf(it.id)} من ${l.length}. ` +
        `الأسهمُ تحرّكه، والمسافةُ تُدخله الشريطَ أو تُخرجه منه.`);
      // ⭐ **يسارَ عناصر يوتيوب في الحاوية نفسِها** — **وهو ما يفعله الحقنُ
      // الحقيقيّ**: `placeInHostBar` تُدرج عند `slot.firstChild` ⇒ **فالمعاينةُ
      // تُري الموضعَ الذي يقع، لا موضعاً نختاره لها.**
      if (it.on) {
        const firstYt = gRight.querySelector("[data-vz-yt]");
        if (firstYt) gRight.insertBefore(chip, firstYt); else gRight.appendChild(chip);
      } else {
        tray.appendChild(chip);
      }

      const hb = vzUiHelpButton(doc, `help_bar_${it.id}`, m.label);
      const body = doc.createElement("p");
      body.className = "vzHelpBody";
      body.id = `help_bar_${it.id}`;
      body.hidden = true;
      body.textContent = m.help;
      const row = doc.createElement("div");
      row.className = "vzSimHelpRow";
      const nm = doc.createElement("span");
      nm.className = "vzBarName";
      nm.textContent = m.label;
      row.appendChild(nm);
      row.appendChild(hb);
      helps.appendChild(row);
      helps.appendChild(body);
    }
    vzUiWireHelp(doc, helps);
  }

  const focusChip = (id) => {
    const el = root.querySelector(`[data-vz-bar-id="${id}"]`);
    if (el) el.focus();
  };

  // **الأسهمُ تحرّك في القائمة كلِّها** — فالموضعُ محفوظٌ داخلَ الشريط وخارجَه معاً
  function move(id, delta) {
    const l = list();
    const i = l.findIndex((x) => x.id === id);
    const j = i + delta;
    if (i === -1 || j < 0 || j >= l.length) return;
    const next = l.slice();
    [next[i], next[j]] = [next[j], next[i]];
    set && set(next);
    render();
    focusChip(id);
    const it = next[j];
    say(`${meta(id).label}: ${it.on ? VZ_SIM_ZONES.in : VZ_SIM_ZONES.out}، الموضع ${j + 1} من ${next.length}`);
  }

  function setZone(id, on) {
    const l = list();
    if (!l.some((x) => x.id === id && x.on !== on)) return;
    const next = l.map((x) => (x.id === id ? { id: x.id, on } : x));
    set && set(next);
    render();
    focusChip(id);
    // ⭐ **والموضعُ يُقال صريحاً مع المنطقة** — فالإطفاءُ يحفظه، وهو سببُ الشكل كلِّه
    say(`${meta(id).label}: ${on ? VZ_SIM_ZONES.in : VZ_SIM_ZONES.out} — وموضعُه ${posOf(id)} محفوظ`);
  }

  root.addEventListener("keydown", (e) => {
    const chip = e.target && e.target.closest && e.target.closest("[data-vz-bar-id]");
    if (!chip) return;
    const id = chip.dataset.vzBarId;
    const on = !chip.classList.contains("vzSimOff");
    if (e.key === "ArrowLeft" || e.key === "ArrowUp") { e.preventDefault(); move(id, -1); }
    else if (e.key === "ArrowRight" || e.key === "ArrowDown") { e.preventDefault(); move(id, +1); }
    else if (e.key === " " || e.key === "Spacebar" || e.key === "Enter") { e.preventDefault(); setZone(id, !on); }
  });

  let dragId = null;
  root.addEventListener("dragstart", (e) => {
    const chip = e.target && e.target.closest && e.target.closest("[data-vz-bar-id]");
    if (!chip) return;
    dragId = chip.dataset.vzBarId;
    if (e.dataTransfer) e.dataTransfer.effectAllowed = "move";
  });
  root.addEventListener("dragend", () => { dragId = null; });
  root.addEventListener("dragover", (e) => { if (dragId) e.preventDefault(); });
  root.addEventListener("drop", (e) => {
    if (!dragId) return;
    e.preventDefault();
    const id = dragId; dragId = null;
    const overChip = e.target && e.target.closest && e.target.closest("[data-vz-bar-id]");
    const zoneEl = e.target && e.target.closest && e.target.closest("[data-vz-zone]");
    if (overChip && overChip.dataset.vzBarId !== id) {
      const l = list();
      const from = l.findIndex((x) => x.id === id);
      const to = l.findIndex((x) => x.id === overChip.dataset.vzBarId);
      if (from !== -1 && to !== -1) {
        const next = l.slice();
        next.splice(to, 0, next.splice(from, 1)[0]);
        // **والإفلاتُ على زرٍّ يتبنّى منطقتَه كذلك** — فالسحبُ من الدرج إلى الشريط
        // **فوق زرٍّ فيه** يجب أن يُفعّله، لا أن يُرتّبه في الدرج.
        const zone = zoneEl ? zoneEl.dataset.vzZone : null;
        const on = zone ? zone === "in" : next[to].on;
        set && set(next.map((x) => (x.id === id ? { id, on } : x)));
        render();
        focusChip(id);
        say(`${meta(id).label}: ${on ? VZ_SIM_ZONES.in : VZ_SIM_ZONES.out}، الموضع ${to + 1} من ${next.length}`);
      }
      return;
    }
    if (zoneEl) setZone(id, zoneEl.dataset.vzZone === "in");
  });

  render();
  return { render };
}

// ── التلميح: **الظهور يُشتقّ ولا يُخزَّن** (البند #84، قرار المالك 2026-08-03) ──
//
//        ظاهر = (المؤشّر فوقه) **أو** (التركيز عليه)
//
// ⛔ **والشكل القديم مسحوب (قرار 21):** ~~`click` يقلب · و`focus`/`mouseenter`
// يفتحان · ولا مخرج~~. **قِيس فتبيّن أن `blur` و`mouseleave` لا يُغلقان**،
// **و`click` يقلب فيُغلق ما فتحه الوصول** ⇒ **`Tab` إليه يفتح الشرح ثمّ `Enter`
// يُغلقه**، فكانت خطوةُ المالك تُنتج **بلاغ فشلٍ عن سلوكٍ صحيح**.
//
// ⇒ **والعلّة مبدئية: مفتاحُ حالةٍ واحد يقلبه أربعة مداخل يُنتج مدخلاً يُلغي أثر
// آخر.** **والاشتقاق من مدخلين مستقلَّين يجعل ذلك مستحيلاً بالبناء لا محروساً** —
// «موضعٌ واحد للحقيقة أو تُشتقّ»، **والثانية هنا أرخص**.
//
// **ولا `click` بذاته:** النقر **يمنح التركيز** فيظهر بالاشتقاق — **واللمس يعمل
// بلا مسارٍ خاصّ**: النقر يمنح، والنقر بعيداً يُزيل.
//
// ⚠️ **و`Esc` يُزيل التركيز صراحةً لا اعتماداً على سلوكٍ افتراضيّ:** «`Esc` يُبعد
// التركيز» **دعوى لم تُقَس عندنا** — والتركيز لا يعمل في المتصفّح المقطوع الرأس
// فلا سبيل إلى قياسها. ⇒ **فتُنفَّذ ولا تُفترض**، وهي **مدخلٌ إلى المصدر نفسه
// (التركيز) لا مفتاحُ حالةٍ ثانٍ** — فالاشتقاق يبقى واحداً.
// **وبه يسقط «حدّ `Esc` المعروف» بدل أن يُوثَّق.**
//
// ⭐ **والحالة التي تكشف الفرق:** `Tab` إليه (يظهر) ثمّ حوّم عليه ثمّ ابعد
// المؤشّر ⇒ **يبقى ظاهراً لأن التركيز باقٍ**. **ومفتاحٌ واحد كان سيُغلقه.**
function vzUiWireHelp(doc, root) {
  for (const b of root.querySelectorAll(".vzHelp")) {
    const body = doc.getElementById(b.getAttribute("aria-controls"));
    if (!body) continue;
    let hovered = false, focused = false;
    const apply = () => {
      const on = hovered || focused;              // **الاشتقاق، ولا حالة تُخزَّن**
      body.hidden = !on;
      b.setAttribute("aria-expanded", String(on));
    };
    b.addEventListener("mouseenter", () => { hovered = true;  apply(); });
    b.addEventListener("mouseleave", () => { hovered = false; apply(); });
    b.addEventListener("focus",      () => { focused = true;  apply(); });
    b.addEventListener("blur",       () => { focused = false; apply(); });
    b.addEventListener("keydown", (e) => { if (e.key === "Escape") b.blur(); });
  }
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { VZ_IDLE_MIN_MS, VZ_UI_GROUPS, VZ_UI_CLEAN, VZ_UI_TIMING,
    VZ_UI_HOSTS, VZ_UI_SUBS, VZ_SCOPE, VZ_BAR_BUTTONS, vzUiBuildBarEditor,
    vzUiBuildClean, vzUiBuildTiming, vzUiBuildList, vzUiControl,
    vzUiWireHelp, vzUiRow, vzUiHelpButton, VZ_SIM_ICONS, vzSvg };
}
